"use client";

import React, { InputHTMLAttributes } from "react";

import { Field } from "./Field";
import { useFieldDescription } from "../hooks/useFieldDescription";
import { useStableId } from "../hooks/useStableId";
import { progressPercentage } from "../utils/numbers";
import styles from "./Slider.module.css";

export interface SliderProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, "type" | "helperText"> {
  label?: string;
  labelStyle?: "plain" | "notch";
  /** Diamond uses a slim track and a square thumb that rotates while held. */
  variant?: "default" | "diamond";
  min?: number;
  max?: number;
  step?: number;
  showValue?: boolean;
  helperText?: string;
  error?: string;
}

/** Fill percentage for the track; 0 when max===min or non-finite. Clamped to [0, 100]. */
export function sliderPercentage(
  value: number | string,
  min: number,
  max: number,
): number {
  return progressPercentage(Number(value), min, max);
}

export function Slider({
  label,
  labelStyle = "plain",
  variant = "default",
  className = "",
  id,
  min = 0,
  max = 100,
  step = 1,
  showValue = true,
  value,
  defaultValue,
  onChange,
  helperText,
  error,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
  ...props
}: SliderProps) {
  const inputId = useStableId("slider", id);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const [internalValue, setInternalValue] = React.useState<number | string>(
    (defaultValue as number | string | undefined) ?? min,
  );
  const currentValue = (value as number | string | undefined) ?? internalValue;
  const percentage = sliderPercentage(currentValue, min, max);

  React.useLayoutEffect(() => {
    const input = inputRef.current;
    if (!input || value !== undefined) return;
    const sync = () => setInternalValue(input.value);
    sync();
    // Form reset restores the DOM value after the reset event has been dispatched.
    const reset = () => queueMicrotask(sync);
    const form = input.form;
    form?.addEventListener("reset", reset);

    return () => form?.removeEventListener("reset", reset);
  }, [value, defaultValue, min, max, step, props.form]);
  const { errorId, hasError, helperId, describedBy } = useFieldDescription({
    prefix: "slider",
    helperText,
    error,
    describedBy: ariaDescribedBy,
  });

  const control = (<div className={styles.sliderContainer}>
        <div
          className={styles.track}
          style={
            {
              ["--slider-percentage" as string]: percentage,
            } as React.CSSProperties
          }
        >
          <div className={styles.trackBase} aria-hidden="true" />
          <div className={styles.fill} aria-hidden="true" />
          <input
            ref={inputRef}
            id={inputId}
            type="range"
            min={min}
            max={max}
            step={step}
            value={value}
            defaultValue={
              value === undefined ? (defaultValue ?? min) : undefined
            }
            className={styles.slider}
            {...props}
            onChange={(event) => {
              if (value === undefined)
                setInternalValue(event.currentTarget.value);
              onChange?.(event);
            }}
            aria-invalid={ariaInvalid ?? (hasError ? true : undefined)}
            aria-describedby={describedBy}
          />
        </div>
        {showValue ? (
          <span className={styles.value}>{currentValue}</span>
        ) : null}
      </div>);


  return (
    <div
      className={`${styles.wrapper} ${variant === "diamond" ? styles.diamond : ""} ${hasError ? styles.hasError : ""} ${className}`.trim()}
    >
      {label && labelStyle === "plain" ? (
        <label htmlFor={inputId} className={styles.label}>
          {label}
        </label>
      ) : null}
      {labelStyle === "notch" ? (
        <Field id={inputId} label={label} labelStyle="notch" invalid={ariaInvalid ?? (hasError ? true : undefined)}
          style={{ "--field-width": "100%" } as React.CSSProperties}>
          {() => <div className={styles.notchedControl}>{control}</div>}
        </Field>
      ) : control}
      {helperText ? (
        <div id={helperId} className={styles.helperText}>
          {helperText}
        </div>
      ) : null}
      {hasError ? (
        <div id={errorId} className={styles.errorText} role="alert">
          {error}
        </div>
      ) : null}
    </div>
  );
}

.wrapper {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.label {
  font-size: 0.875rem;
  color: var(--text-primary);
  font-weight: 500;
}

.sliderContainer {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.track {
  --thumb-size: 28px;
  position: relative;
  flex: 1;
  height: 32px;
  display: flex;
  align-items: center;
}

.trackBase {
  position: absolute;
  inset-inline: 0;
  height: var(--thumb-size);
  border: 2px solid var(--border);
  border-radius: calc(var(--thumb-size) / 2);
  background: var(--bg-primary);
  pointer-events: none;
  transition: border-color var(--transition-fast);
}

.fill {
  position: absolute;
  left: 0;
  height: var(--thumb-size);
  border-radius: calc(var(--thumb-size) / 2);
  background: var(--success);
  /* End at the thumb's outer edge so the fill's rounded cap is the thumb
     circle itself: one capsule at every value, no waist where they meet. */
  width: calc(
    var(--thumb-size) +
      (100% - var(--thumb-size)) * var(--slider-percentage, 0) / 100
  );
  pointer-events: none;
  transition: width var(--transition-fast);
}

.slider {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 32px;
  margin: 0;
  padding: 0;
  appearance: none;
  background: transparent;
  outline: none;
  cursor: pointer;
}

.slider::-webkit-slider-runnable-track {
  height: var(--thumb-size);
  background: transparent;
  border: none;
}

.slider::-webkit-slider-thumb {
  appearance: none;
  /* Border-box keeps the native thumb exactly --thumb-size, so its center
     matches the fill geometry; a border would add 4px and offset the knob. */
  box-sizing: border-box;
  width: var(--thumb-size);
  height: var(--thumb-size);
  margin-top: 0;
  border-radius: 50%;
  background: var(--success);
  cursor: pointer;
  border: 0;
  box-shadow: 0 0 10px color-mix(in srgb, var(--success) 40%, transparent);
  transition: box-shadow var(--transition-fast);
}

.slider::-moz-range-track {
  height: var(--thumb-size);
  background: transparent;
  border: none;
}

.slider::-moz-range-thumb {
  box-sizing: border-box;
  width: var(--thumb-size);
  height: var(--thumb-size);
  border-radius: 50%;
  background: var(--success);
  cursor: pointer;
  border: 0;
  box-shadow: 0 0 10px color-mix(in srgb, var(--success) 40%, transparent);
  transition: box-shadow var(--transition-fast);
}

.track:hover .trackBase {
  border-color: var(--success);
}

.slider:focus-visible {
  box-shadow: none;
}

.slider:focus-visible::-webkit-slider-thumb {
  box-shadow:
    0 0 0 2px var(--bg-primary),
    0 0 0 4px color-mix(in srgb, var(--success) 55%, transparent),
    0 0 10px color-mix(in srgb, var(--success) 40%, transparent);
}

.slider:focus-visible::-moz-range-thumb {
  box-shadow:
    0 0 0 2px var(--bg-primary),
    0 0 0 4px color-mix(in srgb, var(--success) 55%, transparent),
    0 0 10px color-mix(in srgb, var(--success) 40%, transparent);
}

.slider:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.track:has(.slider:disabled) .fill,
.track:has(.slider:disabled) .trackBase {
  opacity: 0.5;
}

.value {
  font-size: 0.875rem;
  color: var(--success);
  font-weight: 600;
  min-width: 3rem;
  text-align: center;
  font-family: var(--font-mono);
}

.helperText {
  margin-top: 0.25rem;
  font-size: 0.75rem;
  color: var(--text-secondary);
  font-family: var(--font-mono);
}

.hasError .label {
  color: var(--danger, #ff5c5c);
}

.hasError .trackBase {
  border-color: var(--danger, #ff5c5c);
}

.errorText {
  margin-top: 0.35rem;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  color: var(--danger, #ff5c5c);
  line-height: 1.3;
}

@media (prefers-reduced-motion: reduce) {
  .fill,
  .trackBase,
  .slider::-webkit-slider-thumb,
  .slider::-moz-range-thumb {
    transition: none;
  }
}

/* Slim native track; retain the range input's keyboard and pointer behavior. */
.diamond .track {
  --thumb-size: 20px;
  min-width: 0;
  height: 44px;
}

.diamond .trackBase,
.diamond .fill { display: none; }

.diamond .slider {
  height: 44px;
  touch-action: pan-y;
}

.diamond .slider::-webkit-slider-runnable-track {
  height: 5px;
  border-radius: 999px;
  background: linear-gradient(to right,
    var(--diamond-slider-accent, var(--color-accent, #ee1401)) 0%,
    var(--diamond-slider-accent, var(--color-accent, #ee1401)) calc(var(--slider-percentage, 0) * 1%),
    var(--diamond-slider-track, var(--color-border, #2a2a2a)) calc(var(--slider-percentage, 0) * 1%),
    var(--diamond-slider-track, var(--color-border, #2a2a2a)) 100%);
}

.diamond .slider::-moz-range-track {
  height: 5px;
  border-radius: 999px;
  background: var(--diamond-slider-track, var(--color-border, #2a2a2a));
}

.diamond .slider::-moz-range-progress {
  height: 5px;
  border-radius: 999px;
  background: var(--diamond-slider-accent, var(--color-accent, #ee1401));
}

.diamond .slider::-webkit-slider-thumb {
  box-sizing: border-box;
  width: 20px;
  height: 20px;
  margin-top: -7.5px;
  border: 0;
  border-radius: 0;
  outline: none;
  background: var(--diamond-slider-accent, var(--color-accent, #ee1401));
  box-shadow: none;
  transform: rotate(0deg);
  transition: transform 160ms ease;
}

.diamond .slider::-moz-range-thumb {
  box-sizing: border-box;
  width: 20px;
  height: 20px;
  border: 0;
  border-radius: 0;
  outline: none;
  background: var(--diamond-slider-accent, var(--color-accent, #ee1401));
  box-shadow: none;
  transform: rotate(0deg);
  transition: transform 160ms ease;
}

.diamond .slider:active:not(:disabled)::-webkit-slider-thumb { transform: rotate(45deg); }
.diamond .slider:active:not(:disabled)::-moz-range-thumb { transform: rotate(45deg); }

/* Focus belongs to the whole control; the thumb stays solid with no halo. */
.diamond .slider:focus-visible {
  outline: 2px solid var(--diamond-slider-accent, var(--color-accent, #ee1401));
  outline-offset: 2px;
  box-shadow: none;
}
.diamond .slider:focus-visible::-webkit-slider-thumb { box-shadow: none; }
.diamond .slider:focus-visible::-moz-range-thumb { box-shadow: none; }
.diamond .value { color: var(--diamond-slider-accent, var(--color-accent, #ee1401)); }
.diamond.hasError { --diamond-slider-track: var(--danger, #ff5c5c); }

@media (prefers-reduced-motion: reduce) {
  .diamond .slider::-webkit-slider-thumb { transition: none; }
  .diamond .slider::-moz-range-thumb { transition: none; }
}

.notchedControl { padding: 12px; }
